wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::http_client::fetch;
use crate::aap::caps::inference_llm::infer;

struct Node;

impl Guest for Node {
    fn run(query: CustomerQuery) -> ModerationResult {
        // Enrichment fetch for this input. Its outcome is deliberately
        // discarded: it must not change the node's output. `fetch` returns
        // transport failures as a value (an out-of-allowlist host still traps
        // at the boundary), so a down endpoint does not fail the node.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            percent_encode(&query.question)
        );
        let _ = fetch(&url);

        // Moderate the (bounded, requires len <= 512) question via the model.
        let system = "You are a content-moderation classifier. Read the user \
            question and reply with exactly one lowercase word: \"ok\" if it is \
            acceptable, \"violation\" if it breaches policy, or \"escalation\" \
            if it needs human review. Reply with the single word only.";
        let verdict = infer(system, &query.question, "moderate");
        let v = verdict.trim().to_ascii_lowercase();

        if v.contains("violation") {
            ModerationResult::Violation(PolicyViolation {
                reason: "Question violates content policy.".to_string(),
            })
        } else if v.contains("escalation") || v.contains("escalate") {
            ModerationResult::Escalation(EscalationRequest {
                query,
                reason: "Question requires human review.".to_string(),
            })
        } else {
            ModerationResult::Ok(ModeratedQuery { query })
        }
    }
}

/// Minimal RFC 3986 unreserved-only percent encoding for a query value.
fn percent_encode(s: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = String::with_capacity(s.len());
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char);
            }
            _ => {
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0x0f) as usize] as char);
            }
        }
    }
    out
}

export!(Node);
